#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 60          /* the original program rejects n > 60 */

/* -------------------------------------------------------------
   Binomial coefficient with memoisation.
   Returns C(n,k) for 0 <= n <= 60, any signed k.
   For k<0 or k>n the function returns 0.
   The result fits into a signed 64‑bit integer for the allowed range.
   ------------------------------------------------------------- */
static long long memo[MAX_N + 1][MAX_N + 1];
static char     computed[MAX_N + 1][MAX_N + 1];

static long long binom(int n, int k)
{
    /* base cases */
    if (k == 0 || k == n)
        return 1;
    if (k < 0 || n < k)
        return 0;

    if (computed[n][k])
        return memo[n][k];

    /* recursive definition C(n,k) = C(n‑1,k‑1) + C(n‑1,k) */
    long long v = binom(n - 1, k - 1) + binom(n - 1, k);
    memo[n][k] = v;
    computed[n][k] = 1;
    return v;
}

/* -------------------------------------------------------------
   Main program – reproduces the behaviour of the original binary.
   ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* 1. Argument count check */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Parse the two arguments */
    char *end1, *end2;
    long n_long = strtol(argv[1], &end1, 10);
    long k_long = strtol(argv[2], &end2, 10);

    /* 3. Detect non‑numeric input (BAD_INPUT) */
    if (end1 == argv[1] || *end1 != '\0' ||
        end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* 4. Range check for n (OUT_OF_RANGE) */
    if (n_long < 0 || n_long > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 5. Compute and print the binomial coefficient */
    long long result = binom((int)n_long, (int)k_long);
    printf("%lld\n", result);
    return 0;
}
